/*-----------------------------------------------------------*/
void udp_parse_task(void *arg)
{	
	uint8_t massive[8192] = {0};
	uint32_t global_counter = 1;
	uint16_t azimut = 0;
	bool round_done = false;
	uint16_t value_loc = 159;
	uint8_t average_per_3rounds = 0;
	uint8_t t = 0;
	u8 flag_test = 1;
	controlPtr = createControlArray();
	noise_tracker_t noise = {
		.noise_value_per_packets = {0},
		.packet_count = 0U,
		.ema_q = 0U,
		.alpha_num = 1U,
		.alpha_den = 1024U,   // для 1.2ms/пакет хороший базовый вариант
		.alpha_num_slow = 1U,
		.alpha_den_slow = 2048,
		.max_value_noise = 0xC350,
		.initialized = false
	};
	
	storages_initializ(value_loc - HEADER_SIZE - TIME_SIZE);
	uint8_t *result = (uint8_t*) mem_calloc(value_loc, sizeof(uint8_t));  // Trouble: too much in while(true)
	uint16_t *converted_massive = (uint16_t*) mem_calloc(value_loc - HEADER_SIZE - TIME_SIZE, sizeof(uint16_t));
	
	xil_printf("UDP parse task\r\n");
	while (true)
	{
		// value_loc = xMessageBufferReceive(xPacketBuffer, massive, sizeof(massive), portMAX_DELAY);
		xil_printf("Value %d", value_loc);
		// WE CAN CHANGE THIS DINAMIC MASSIVE with static massive for biggest situation massive(8k) 
		if (result == NULL)
		{
			xil_printf("Result not allocated memory!");
		}
		if (update_mode)
		{
			clean_all();
			mem_free(result);
			mem_free(converted_massive);
			mem_free(controlPtr);
			storages_initializ(value_loc - HEADER_SIZE - TIME_SIZE);
			result = (uint8_t*) mem_calloc(value_loc, sizeof(uint8_t));
			converted_massive = (uint16_t*) mem_calloc(value_loc - HEADER_SIZE - TIME_SIZE, sizeof(uint16_t));
			controlPtr = createControlArray();
			update_mode = false;
		}

		flag_test ^= 1;
		vParTestSetGPIO(IO_L23P_T3_12, flag_test);
		vParTestSetGPIO(IO_L23N_T3_12, flag_test);
		vParTestSetGPIO(IO_L19P_T3_12, flag_test);

		for (size_t i = 0; i < 10; i++)
		{
			bool res = parse_cat240(test_ptr_type10_middle[i], value_loc, metainfo_parser);
			if (res)
			{
				xil_printf("\r\n Counter message %d\r\n", metainfo_parser->msg_index);
			
				if ((metainfo_parser->header_nano.start_az + AVERAGE_DIFFERENCE_AZ) > UINT16_MAX)
				{
					xil_printf("\r\n Round done! \r\n");
					round_done = true;
				}
			
				for (size_t k = 0; k < value_loc - HEADER_SIZE - TIME_SIZE; k += 2)
				{
					if ((metainfo_parser->video_block.data[k] * 0x100 + metainfo_parser->video_block.data[k + 1]) > storage->video_data[k] * 0x100 + storage->video_data[k + 1])
					{
						storage->video_data[k] = metainfo_parser->video_block.data[k];
						storage->video_data[k + 1] = metainfo_parser->video_block.data[k + 1];
					}
				}
				storage->start_az += metainfo_parser->header_nano.start_az;

				if (counter_packets == work_size)
				{
					storage->start_az = storage->start_az / counter_packets;
					storage->end_az = storage->start_az + AVERAGE_DIFFERENCE_AZ;
					counter_packets = 0;
				
					convertTo16(storage->video_data, storage->data_size, converted_massive);
					autoGainControl(storage->start_az, converted_massive, value_loc - HEADER_SIZE - TIME_SIZE, controlPtr);
				
					compose(result, storage);
					result[9]  = (global_counter>> 24) & 0xFF;
					result[10] = (global_counter >> 16) & 0xFF;
					result[11] = (global_counter >> 8) & 0xFF;
					result[12] = global_counter & 0xFF;
				
					cat240_pbuf = pbuf_alloc(PBUF_TRANSPORT, value_loc, PBUF_POOL);
					pbuf_take(cat240_pbuf, result, value_loc);
					err_t err = udp_send(udp_pcb_answer, cat240_pbuf);
					pbuf_free(cat240_pbuf);
				
					uint32_t noise_inst = estimate_packet_noise_u16(storage->video_data, storage->data_size);
					noise.noise_value_per_packets[global_counter] = noise_inst;
					xil_printf("Average in packet %08X", noise_inst);

					
					global_counter++;
				}
				counter_packets++;
				if (global_counter == 1200)
				{
					noise.middle_noise_val_per_3round[t] = get_noise_per_round(&noise, noise.noise_value_per_packets, 1200);
					t++;
					if (t == 3)
					{
						average_per_3rounds = get_noise_per_3rounds(noise.middle_noise_val_per_3round, 3);
						xil_printf("Average in 3 round %08X", average_per_3rounds);
						t == 0;
					}
					global_counter = 1;
				}
			}
		}

		flag_test ^= 1;
		vParTestSetGPIO(IO_L23P_T3_12, flag_test);
		vParTestSetGPIO(IO_L23N_T3_12, flag_test);
		vParTestSetGPIO(IO_L19P_T3_12, flag_test);
		
		vTaskDelay(pdMS_TO_TICKS(20));
	}
}

/*-----------------------------------------------------------*/
void tcp_parse_task(void *arg)
{
	uint8_t payload[10];
	size_t size;
	while(1)
	{
		size = xMessageBufferReceiveFromISR(xMsgBuffer, payload, sizeof(payload), pdMS_TO_TICKS(20));
		if (size > 0)
		{
			xil_printf("\nSize of bytes %02x\n", size);
			parse_msg(payload, size);
		}
		vTaskDelay(pdMS_TO_TICKS(40));
	}
}

/*-----------------------------------------------------------*/
void vStatsTask(void *arg)
{
    start_stop_ttc_timer(TTC_TIMER_CHANNEL_2, 1);
	const TickType_t xPeriod = pdMS_TO_TICKS(5000);
	u8 flag_for_led = 0;
    while(1)
    {
		vParTestSetGPIO(LED_LEFT, flag_for_led);
		flag_for_led ^= 1;
		vTaskDelay(xPeriod);
        if (average % 100 > 10)
		{
        	xil_printf("Average packet sending time via UDP %u,%u\r\n", average * 900 / 100000, average % 100);
		}
		else
		{
			xil_printf("Average packet sending time via UDP %u,0%u\r\n", average * 900 / 100000, average % 100);
		}
		average = 0;
		stats_display();
		need_reconnect(tcp_pcb);
		if (try_reconnect)
		{
			reconnection_tcp(tcp_pcb);
		}
    }
}

/*-----------------------------------------------------------*/
void vTcpStatTask(void *arg)
{
    xil_printf("Task monitoring tcp");
	const TickType_t monitor_interval = pdMS_TO_TICKS(30000);
	while (1)
	{
		update_monitor(monitor);
		print_status(monitor);
		
		vTaskDelay(monitor_interval);
	}
}

/*-----------------------------------------------------------*/
void x1emacif_input_thread(void *arg)
{
    struct netif *netif = (struct netif *)arg;
    while(1)
    {
        if(TcpFastTmrFlag)
		{
			tcp_fasttmr();
			TcpFastTmrFlag = 0;
		}
		if (TcpSlowTmrFlag)
		{
			tcp_slowtmr();
			TcpSlowTmrFlag = 0;
		}
		xemacif_input(netif);
        vTaskDelay(pdMS_TO_TICKS(30));
    }
}
